const sketch = (p5obj:any) => {
/**
この作品は江戸切子をモチーフとした作品です。江戸切子は、ガラスに繊細な紋様を施し
た江戸川区の伝統工芸品で、その美しさと連続して見える紋様が、今回の課題の要点であ
る「再起」とマッチしていると思ったからです。また、私の住んでいる場所が江戸川区だ
からというのも理由の一つです。
*/
p5obj.setup = () => 
{
  p5obj.colorMode(p5obj.HSB,360,30,30);
  p5obj.createCanvas( 1000, 1000);
  p5obj.background('#66cdaa');
  p5obj.strokeWeight(1);
  p5obj.strokeCap(p5obj.PROJECT);
  let hueVal: number = p5obj.random(360);
  p5obj.stroke(hueVal,100,100);
  drawTuta(p5obj.random(0,p5obj.width),p5obj.height/2,700,20,10 );
}

const drawTuta = (fBeginX: number, fBeginY: number, fLength: number, fDegree: number, iLevel: number) => { 
 
  let fEndX: number = fBeginX + fLength * p5obj.cos( p5obj.radians( fDegree ) );
  let fEndY: number = fBeginY + fLength * p5obj.sin( p5obj.radians( fDegree ) );
  
  p5obj.line(fBeginX,fBeginY,fEndX,fEndY);
  
  if( iLevel > 1 )
  {
    drawTuta( fEndX,fEndY,fLength,fDegree+40,iLevel - 1 ); 
    drawTuta( fEndX,fEndY,fLength,fDegree-40,iLevel - 1 ); 
    drawTuta( fEndX,fEndY,fLength,fDegree-60,iLevel - 1 ); 
    
  }
}

};

export default sketch;
