const sketch = (p5obj:any) => {
    p5obj.setup = () => {
p5obj.createCanvas(500, 500);
p5obj.background(255);

var a=20;

p5obj.noStroke();
p5obj.fill(255, 20, 147, 50);
for (var f=0; f<60; f++)
{
  for (var e=0; e<60; e++)
  {
    p5obj.circle(20+60*f, 10+60*e, 10);
    p5obj.circle(-10+60*e, -20+60*f, 10);
  }
}

p5obj.push();
p5obj.translate(-a*2, -a*2);
for (var x=0; x<=600; x=x+60)
{
  for (var y=0; y<=600; y=y+60)
  {
    p5obj.fill(p5obj.random(60, 100), p5obj.random(120, 255), p5obj.random(150, 200), 170);
    p5obj.noStroke();
    p5obj.stroke(0, p5obj.random(150, 200), 255, 50);

    p5obj.quad(x+0, y+0, x+50, y+50, x+ 0, y+100, -50+x, y+50);
  }
}
p5obj.push();
for (var x=0; x<=600; x=x+200)
{
  for (var y=0; y<=600; y=y+200)
  {
    p5obj.fill(255, 20);
    p5obj.strokeWeight(3);
  }
}

for (var c=0; c<500; c++)
{
  for (var d=0; d<500; d++)
  {
    p5obj.circle(20+60*d, 10+60*c, 60);
    p5obj.circle(-10+60*c, -20+60*d, 60);
    p5obj.stroke(p5obj.random(100, 255), p5obj.random(120, 200), p5obj.random(200, 220));
  }
}

  };
};

export default sketch;
