const sketch = (p5obj:any) => {
/*
 
シンプルに雪の結晶を作ってみました。下記Configから値を変更することができます。
ついでにノードの深度に応じて色を変えられるようにしました。
自然界では氷の結晶構造が正四面体構造であるため、雪の結晶は6方向にしか伸びないのですが
centerDivの値を10とかにしてみると自然界にない形になります。結構おすすめです。
逆に4方向とか3方向とかも。数学的処理のいいところは物理的制限を回避した理論上の形が取れる所だと思います。
難しさでもあるんですけどね。

*/


//---------------------------------Config---------------------------------//

//------結晶らに関する設定------//
let snowAlpha: number = 50;             //背後の雪結晶の透明度(0-255)
let snowAmount: number = 8;             //雪結晶の量
let circleAmount: number = 10;          //雰囲気付けの量(設定値 * snowAmount 個)

//------中心に関する設定------//
let centerDiv: number = 6;            //中心分岐数
let maxR: number = 300;             //1st Nodeの最大長さ
let minR: number = maxR * 0.4;      //1st Nodeの最小長さ


//------ノード分岐に関する設定------//
let maxLevel: number = 4;                   //再帰する数 (設定値 → 中心の深度, 外側に向けて減衰)
let divAngle: number = p5obj.radians(30);       //分割するときの角度 (0-360度)
let divRatio: number = 0.25;              //何%おきにノードを配置するか (0-1)

//------------------------------------------------------------------------//




//---------------------------------初期設定---------------------------------//
p5obj.setup = () => 
{
  p5obj.createCanvas(1000, 1000);
  p5obj.background(0, 0, 0);
  p5obj.colorMode(p5obj.RGB);

  let x: number = 0;

  let y: number = 0;

  let r: number = 0;


  for (let i: number = 0; i<snowAmount; i++) {
    
    p5obj.fill(0, snowAlpha);
    p5obj.rect(0,0,p5obj.width,p5obj.height);
    
    //ランダム座標に結晶を描画(中心よりガウス分布で展開)
    x =(p5obj.width/2 * (1 + p5obj.randomGaussian()/2));
    y =(p5obj.height/2 * (1 + p5obj.randomGaussian()/2));
    r = p5obj.random(minR, maxR);

    makeSnow(x, y, r, centerDiv);
    
    
    //雰囲気付け (丸描画)
    for (let k: number = 0; k<10; k++) {
      x =(p5obj.random(0,p5obj.width));
      y =(p5obj.random(0,p5obj.height));
      r = p5obj.random(minR*0.05, maxR*0.1);
      
      p5obj.stroke(255, 255, 255);
      p5obj.circle(x,y,r);
    }
  }
}




//---------------------------------Main---------------------------------//
//雪の結晶を描画する(中心のx,y, 半径, 中心分岐数)
const makeSnow = (x: number, y: number, r: number, centerDiv: number) => {
  for (let i: number = 1; i<=centerDiv; i++) {

    //中心を(centerDiv)分割してノードを生やす
    drawNode(maxLevel, x, y, r, p5obj.radians(360/centerDiv * i));
  }
}



//---------------------------------Recursion---------------------------------//
//エッジを追加し、ノードを再帰する(現在の深度, 始端のx,y, 半径, 角度)
const drawNode = (level: number, fromX: number, fromY: number, r: number, angle: number) => {

  //------エッジの描画------//
  //終点Node作成
  let toX: number = fromX + (r * p5obj.cos(angle));
  let toY: number = fromY + (r * p5obj.sin(angle));
  
  //Nodeの深度によって色を変更してみる
  let Blueness: number = 250 - (level-1) * 20;
  p5obj.stroke(Blueness, Blueness, 255);

  //描画
  p5obj.line(fromX, fromY, toX, toY);
  //p5obj.text(level, toX, toY); //For Debug


  //------次のノードを作成------//
  if (level > 1) {

    //一本のエッジに対して(divRatio)%の距離おきにノードを追加したい
    let radius: number = r * divRatio;

    //(divRatio)%の距離おきに、元の長さを超えない程度までノードを追加し続け、再帰する
    for (let k: number = 1; divRatio*k <= 1; k++) {

      //分岐点のノードを作成 (±Angleで正しく実行されるように、toXYとは座標変数を分ける必要がある)
      fromX = fromX + (radius * p5obj.cos(angle));
      fromY = fromY + (radius * p5obj.sin(angle));
      //p5obj.circle(fromX,fromY,5); //For Debug

      //再帰する
      drawNode(level - 1, fromX, fromY, r*0.5/p5obj.sqrt(k), angle + divAngle);
      drawNode(level - 1, fromX, fromY, r*0.5/p5obj.sqrt(k), angle - divAngle);
    }
  }
}

};

export default sketch;
