const sketch = (p5obj:any) => {
/**
 
 ビーカーに注がれる液体の水嵩で測る時計
 １秒で１メモリ,時間が経つにつれて色が変わっていく
 
 */

let iW: number;

p5obj.setup = () => 
{
  p5obj.frameRate(60);//フレームレートを60に設定
  p5obj.createCanvas(600, 600);//サイズを600×600に設定
  p5obj.colorMode(p5obj.HSB, 360, 100, 100, 100);//カラーモードをRGBに設定
  p5obj.background(0);//背景色

  iW = 0;
}

p5obj.draw = () => 
{

  //画面リフレッシュ-----------------------------
  p5obj.fill(0);
  p5obj.rect(0, 0, p5obj.width, p5obj.height);

  //ビーカー-------------------------------------
  p5obj.fill(255);
  p5obj.noStroke();
  p5obj.rectMode(p5obj.CORNERS);
  p5obj.rect(200, 300, 400, 565);
  p5obj.rect(185, 290, 400, 300);

  p5obj.fill(255);
  p5obj.noStroke();
  p5obj.rectMode(p5obj.CORNERS);
  p5obj.rect(200, 300, 400, 565);
  p5obj.rect(185, 290, 400, 300);


  //水滴の描画------------------------------------

  p5obj.translate(0, 365);//振動の中心を移動
  iW += 3;         //角度は3°ずつ上がって行く
  p5obj.fill(125, 80, 275);
  p5obj.circle(p5obj.width/2, -185*p5obj.cos(p5obj.radians(iW)), 12.5);    //振幅185,振動の中心(300,365)の単振動

  //180°を超えると0°に戻る
  if (iW > 180)
  {
    iW = 0;
  }

  //座標リセット-----------------------------------
  p5obj.translate(0, -365);

  //時計-------------------------------------------

  //秒刻み

  let s: number = p5obj.second();
  let m: number = p5obj.minute();


  let iX: number = 560-4.5*s;    //１秒ごとに１メモリずつ上がっていくiX

  p5obj.noStroke();
  p5obj.fill(m*6, 40, 90);   //１分ごとにHSBのHの値が6°ずつ上がる
  p5obj.rect(395, 560, 205, iX);


  //メモリ
  p5obj.stroke(0);
  p5obj.strokeWeight(1.5);
  p5obj.line(200, 537.5, 210, 537.5);
  p5obj.line(200, 515, 215, 515);
  p5obj.line(200, 492.5, 210, 492.5);
  p5obj.line(200, 470, 215, 470);
  p5obj.line(200, 447.5, 210, 447.5);
  p5obj.line(200, 425, 215, 425);
  p5obj.line(200, 402.5, 210, 402.5);
  p5obj.line(200, 380, 215, 380);
  p5obj.line(200, 357.5, 210, 357.5);
  p5obj.line(200, 335, 215, 335);
  p5obj.line(200, 312.5, 210, 312.5);


  //メモリ文字
  p5obj.fill(0);
  p5obj.textSize(12.5);
  p5obj.textAlign(p5obj.CENTER);
  p5obj.text(10, 225, 515);
  p5obj.text(20, 225, 470);
  p5obj.text(30, 225, 425);
  p5obj.text(40, 225, 380);
  p5obj.text(50, 225, 335);

  //１分ごとに泡のアニメーション


  //試験管-----------------------------------------
  p5obj.fill(255);
  p5obj.translate(285, 100);
  p5obj.rotate(p5obj.radians(75));
  p5obj.noStroke();
  p5obj.rect(10, 10, 60, 355);
  p5obj.rect(5, 5, 65, 12);

  //試験管液体
  p5obj.noStroke();
  p5obj.fill(125, 80, 275);
  p5obj.triangle(12, 265, 58, 5, 58, 10000);

  //試験管メモリ
  p5obj.stroke(0);
  p5obj.line(10, 332.5, 20, 332.5);
  p5obj.line(10, 310, 20, 310);
  p5obj.line(10, 287.5, 20, 287.5);
  p5obj.line(10, 265, 20, 265);
  p5obj.line(10, 242.5, 20, 242.5);
  p5obj.line(10, 220, 20, 220);
  p5obj.line(10, 197.5, 20, 197.5);
  p5obj.line(10, 175, 20, 175);
  p5obj.line(10, 152.5, 20, 152);
  p5obj.line(10, 130, 20, 130);
  p5obj.line(10, 107.5, 20, 107.5);
  p5obj.line(10, 85, 20, 85);
  p5obj.line(10, 62.5, 20, 62.5);
  p5obj.line(10, 40, 20, 40);
  p5obj.line(10, 17.5, 20, 17.5);
}

};

export default sketch;
